UIMissileLaunchEmitter=function(game){Phaser.Particles.Arcade.Emitter.call(this,game,0,0,40);this.particleClass=UISmokeParticle;this.makeParticles('game',['smoke0','smoke1','smoke2']);this.particleDrag.setTo(50,50);this.setAlpha(0.8,1.0);this.setRotation(0,0);this.minParticleScale=UIConstants.GAME_ASSET_SCALE*0.8;this.maxParticleScale=UIConstants.GAME_ASSET_SCALE*1.0;this.gravity=0;this.kill();this.visible=false;};UIMissileLaunchEmitter.prototype=Object.create(Phaser.Particles.Arcade.Emitter.prototype);UIMissileLaunchEmitter.prototype.constructor=UIMissileLaunchEmitter;UIMissileLaunchEmitter.prototype.preUpdate=function(){if(!this.exists||this.game.physics.arcade.isPaused){return false;}return Phaser.Particles.Arcade.Emitter.prototype.preUpdate.call(this);};UIMissileLaunchEmitter.prototype.update=function(){if(!this.exists||this.game.physics.arcade.isPaused){return;}Phaser.Particles.Arcade.Emitter.prototype.update.call(this);if(this.countLiving()==0){this.kill();this.visible=false;}};UIMissileLaunchEmitter.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.postUpdate.call(this);};UIMissileLaunchEmitter.prototype.spawn=function(x,y,rotation){this.revive();this.visible=true;this.x=x;this.y=y;var speed=-MathUtils.randomRange(UIConstants.MISSILE_LAUNCH_MIN_SPEED,UIConstants.MISSILE_LAUNCH_MAX_SPEED);var speedX=Math.sin(rotation)*speed;var speedY=-Math.cos(rotation)*speed;this.minParticleSpeed.setTo(speedX-65,speedY-65);this.maxParticleSpeed.setTo(speedX+65,speedY+65);this.explode(2000,QualityManager.getQualityValue(QualityManager.QUALITY_PARAMETERS.MISSILE_LAUNCH_SMOKE_COUNT));};UIMissileLaunchEmitter.prototype.retire=function(){this.kill();this.visible=false;this.callAll('retire');};